def _logo(nom, jpeg=False):
    """Logo livré dans frontend/public/assets/print, en data URL (vide si le fichier manque)."""
    import base64
    import io
    from pathlib import Path

    from django.conf import settings

    chemin = Path(settings.BASE_DIR) / "frontend" / "public" / "assets" / "print" / nom
    if not chemin.exists():
        return ""
    contenu, type_mime = chemin.read_bytes(), "image/jpeg" if nom.endswith(".jpg") else "image/png"
    if jpeg:
        try:
            from PIL import Image

            tampon = io.BytesIO()
            Image.open(chemin).convert("RGB").save(tampon, "JPEG", quality=88, optimize=True)
            contenu, type_mime = tampon.getvalue(), "image/jpeg"
        except Exception:
            pass
    return f"data:{type_mime};base64,{base64.b64encode(contenu).decode()}"


